mapper.select:
select M.*, C.message_sender_id, C.message_sender_nickname, C.message_sender_level, S.message_level from message M left outer join message_chat C on M.message_no = C.message_no left outer join message_system S on M.message_no = S.message_no where M.message_room = #{messageRoom} order by M.message_no desc
select * from ( select * from (
select * from temp_list
where message_no < #{lastMessageNo}
)
where rownum <= #{size}
) order by message_no asc

select M.*, C.message_sender_id, C.message_sender_nickname, C.message_sender_level, S.message_level from message M left outer join message_chat C on M.message_no = C.message_no left outer join message_system S on M.message_no = S.message_no where M.message_room = #{messageRoom} order by M.message_no desc
